style.css:
@media (max-width: 770px) {
.now-playing-bar {
    width: 500px !important;
}

.now-playing-bar-container {
    min-width: 300px !important;
    height: 70px !important;
}

.now-playing-bar__right {
    display: none !important;
}

.now-playing-bar__left {
    width: 250px;
}

.now-playing-bar__center {
    width: 220px;
}

nav.Root__nav-bar {position: absolute; clip-path: inset(0); transition: .15s ease-out .15s;}
nav.Root__nav-bar:not(:hover):not(:focus-within) {clip-path: inset(0 calc(100% - 64px) calc(100% - 64px) 0); transform: translate(-23px, -22px);}
}
